class BatchTaggingPayload(BaseModel):
    asset_ids: List[int]
    tags: List[str]

    @field_validator("asset_ids")
    def validate_asset_count(cls, ids: List[int]) -> List[int]:
        if len(ids) == 0:
            raise ValueError("asset_ids list cannot be empty")
        if len(ids) > 100:
            raise ValueError("Maximum 100 assets permitted per batch")
        return ids

@router.patch("/dam/assets/batch-tags")
def batch_assign_tags(
    payload: BatchTaggingPayload,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    updated = db.query(DigitalAsset).filter(
        DigitalAsset.id.in_(payload.asset_ids),
        DigitalAsset.creator_id == user.id
    ).update({"metadata_tags": payload.tags}, synchronize_session=False)
    db.commit()
    return {"updated_count": updated}
